import assert from 'node:assert/strict';
import {packContext} from './context-packet.js';

// maxBytes must be a nonnegative safe integer; 1.5 is not
assert.throws(() => packContext([], 1.5), Error);

// negative maxBytes is invalid
assert.throws(() => packContext([], -1), Error);

// non-integer maxBytes is invalid
assert.throws(() => packContext([], 0.5), Error);

// safe integer boundary: MAX_SAFE_INTEGER is valid
const r1 = packContext([], Number.MAX_SAFE_INTEGER);
assert.deepEqual(r1, {text:'', bytes:0, included:[], omitted:[]});

// MAX_SAFE_INTEGER + 1 is NOT a safe integer
assert.throws(() => packContext([], Number.MAX_SAFE_INTEGER + 1), Error);

// sections must be a dense array; missing slots are invalid
assert.throws(() => packContext(new Array(1), 100), Error);

// null section is invalid
assert.throws(() => packContext([null], 100), Error);

// array section is invalid
assert.throws(() => packContext([[]], 100), Error);

// non-object section is invalid
assert.throws(() => packContext(['str'], 100), Error);

// empty id is invalid
assert.throws(() => packContext([{id:'', text:'', priority:0, required:false}], 100), Error);

// non-string id is invalid
assert.throws(() => packContext([{id:1, text:'', priority:0, required:false}], 100), Error);

// non-string text is invalid
assert.throws(() => packContext([{id:'a', text:1, priority:0, required:false}], 100), Error);

// negative priority is invalid
assert.throws(() => packContext([{id:'a', text:'', priority:-1, required:false}], 100), Error);

// non-boolean required is invalid
assert.throws(() => packContext([{id:'a', text:'', priority:0, required:'yes'}], 100), Error);

// duplicate IDs are invalid
assert.throws(() => packContext([{id:'x', text:'', priority:0, required:false},{id:'x', text:'', priority:0, required:false}], 100), Error);

// case-sensitive IDs: 'A' and 'a' are distinct
const r2 = packContext([{id:'A', text:'a', priority:0, required:false},{id:'a', text:'b', priority:0, required:false}], 100);
assert.deepEqual(r2.included, ['A','a']);

// __proto__ is a valid ID
const r3 = packContext([{id:'__proto__', text:'p', priority:0, required:false}], 100);
assert.equal(r3.included[0], '__proto__');

// required overflow throws even with valid sections
assert.throws(() => packContext([{id:'r', text:'x'.repeat(100), priority:0, required:true}], 10), Error);

// optional skip continues to later sections
const r4 = packContext(
  [{id:'big', text:'x'.repeat(50), priority:10, required:false},
   {id:'small', text:'y', priority:5, required:false}],
  Buffer.byteLength('### "small"\ny\n', 'utf8')
);
assert.deepEqual(r4.included, ['small']);
assert.deepEqual(r4.omitted, ['big']);

// omitted reported in input order, not priority order
const r5 = packContext(
  [{id:'low', text:'a', priority:1, required:false},
   {id:'high', text:'b', priority:10, required:false}],
  Buffer.byteLength('### "high"\nb\n', 'utf8')
);
assert.deepEqual(r5.included, ['high']);
assert.deepEqual(r5.omitted, ['low']);

// input is not mutated
const input = [{id:'a', text:'x', priority:1, required:false}];
const before = JSON.stringify(input);
packContext(input, 100);
assert.equal(JSON.stringify(input), before);

console.log('all contract checks passed');

